"""Scoped early Campaign3 claim review, retaining original occurrence identities."""
from pathlib import Path
from fractions import Fraction as F
import json,hashlib,copy
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-research-identity-rev1';O.mkdir(exist_ok=True)
SOURCE='reference/RESEARCH.md'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def save(p,v):
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
specs=[(1494, 'REBASELINE', 'Default derived/censored path replaces legacy defaults; old controls remain explicitly callable.', 'Historical single reference path not sole modern topology, no law canonization. Retirement of defaults differs from removing old input surfaces.', ['CAMPAIGN3_HISTORY_RETIREMENTS_CHECKPOINT.md']), (1616, 'SEMANTIC-EXPERIENCE', 'Packaging excludes Overflow and distinguishes perceived event and observed effects.', 'Retained full EffectProvenance is not automatically safe cognition: hidden causal fields require admitted source restriction. Later EPI, not absence of overflow alone, supplies boundary proof.', ['CAMPAIGN3_EPI_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ007_CHECKPOINT.md']), (1650, 'EIGHT-REPLAYS', 'Six survive/two refined within historical eight-item rebaseline; flat half-weight stays control, floor corruption retired as default.', 'Memory fixture not cognitive-cycle replay. Preference/negative substitution overclaims retain HQ001/004 limits; zero outright retraction does not erase prior errors.', ['CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md', 'CAMPAIGN3_HISTORY_HQ004_CHECKPOINT.md']), (1737, 'REBASELINE-SUMMARY', 'Explicit legacy names improve reproducibility and preserve prior tested values.', 'Every-substantive-claim language exceeds eight tested projections; current overcomplete comparison method supersedes constructive-minimalism routing.', ['CAMPAIGN3_HISTORY_HQ010_CHECKPOINT.md']), (1783, 'DECISION-SCOPE', 'Named dilemmas separate from ordinary action pipeline; exact PMF and frozen intent share execution tail.', 'No personality vector invariant was vacuous, not tested constitution. Seed match alone not address match; authored dilemmas not option discovery.', ['CAMPAIGN3_DECISION_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ004_CHECKPOINT.md']), (1830, 'PMF', 'Independent brute-force face enumeration supports exact fair tie-share; normalization distinct.', 'Bounded finite support check, not universal psychology or historical compiler equivalence.', ['CAMPAIGN3_DECISION_QUALIFICATION.md']), (1846, 'CEILING', 'Reported K-ratio calibration explains selected long-run expected balance under stated assumptions.', 'Claim largest strength however many rounds is not pathwise maximum for stochastic samples. Unequal/feedback-dependent evidence changes assumptions; preserve as conditional heuristic, not impossibility proof.', ['CAMPAIGN3_BIO_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_HQ001_002_CHECKPOINT.md']), (1863, 'A-D-K', 'Residual/obvious/trivial/meaningful cases and forced execution isolate intent versus outcome.', 'Authoritative Auto does not roll even if pre-roll probability nonzero; neither-option-dictated phrasing cannot infer stochastic resolution in Auto. All quantities legacy-scoped.', ['CAMPAIGN3_DECISION_QUALIFICATION.md', 'CAMPAIGN3_AGENCY_QUALIFICATION.md']), (1911, 'E-G-H', 'Feedback-off acquisition, feedback-on probe and falling contest demonstrate distinct mechanisms.', 'Off-ablation not ordinary-loop qualification; finite first/last-third comparison not universal stabilization or all-path monotonicity.', ['CAMPAIGN3_BIO_QUALIFICATION.md']), (1949, 'FLOOR', 'Separately floored identity could not rescue the chosen weak option in legacy fixture.', 'Single/channel-specific bound does not generalize arbitrary sums; later shared pool rescues genuine weak motive. No universal dice impossibility; original failure retained.', ['CAMPAIGN3_REASON_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_COUNTEREXAMPLES_CHECKPOINT.md']), (1995, 'CONTRADICTION', 'Feedback-off contrary behavior erodes while original feedback-on condition resists.', 'Different questions, not same-loop transformation proof; later2.95 stronger bias qualifies specific on-feedback erosion.', ['CAMPAIGN3_BIO_QUALIFICATION.md']), (2023, 'SEED', 'Paired seeds produce acquired-state and later-probability divergence under tuned moderate fixture.', 'Seed changes all addressed draws including outcomes, not early dice only. Later PREIDENTITY matched intervention supplies separate narrower causal proof.', ['CAMPAIGN3_IDENTITY_ABLATION_SUMMARY_REV2.json']), (2052, 'IDENTITY-SUMMARY', 'Historical expressions and evidence permit later audit of acquired feedback.', 'Research history is not automatically observer evidence; no general minimal identity representation or all-seed difference.', ['CAMPAIGN3_IDENTITY_BELIEF_PUBLIC_QUALIFICATION.md']), (2100, 'CONSOLIDATION', 'Two maps keep feedback out of its own evidence while combining raw pressure before shared floor.', 'Fix of historical design, not proof every future source belongs in same pool; modern role distinction remains.', ['CAMPAIGN3_REASON_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_COUNTEREXAMPLES_CHECKPOINT.md']), (2152, 'TARGETS-A-C', '301-step sweep has one large probability jump; weak signals combine; opposing identity narrows lead without reversal.', 'Continuous raw pressure not continuous probability;0.75 baseline already player-facing, not literal Auto-to-contested witness. Parameter search preserved.', ['CAMPAIGN3_HISTORY_COUNTEREXAMPLES_CHECKPOINT.md', 'CAMPAIGN3_REASON_QUALIFICATION.md']), (2199, 'TARGETS-D-E', 'Feedback-on erosion under stronger bias and from-zero acquisition establish declared finite witnesses.', 'Changed9/4 bias not same-input proof versus2; finite plateau not infinite-time absorbing theorem or every-seed trait acquisition.', ['CAMPAIGN3_BIO_QUALIFICATION.md']), (2244, 'CONSOLIDATION-SUMMARY', 'Shared threshold placement changes reachable behavior without new psychological trait.', 'Two-map mechanism remains historical candidate; pooled-channel design later replaced for reason identity, with controls preserved.', ['CAMPAIGN3_REASON_QUALIFICATION.md']), (2290, 'NUCLEI', 'Typed motive/referent/role separate independent reasons; base needed before modifiers activate.', 'Exact identity controlled by source; not learned attribution or arbitrary grammar necessity. Grouping triple and resolved direction distinct.', ['CAMPAIGN3_REASON_QUALIFICATION.md']), (2342, 'NUCLEI-A-C', 'One motive one nucleus, same referent multiple motives, same motive separate referents.', 'Authored vocabulary and exact source attribution bound expressive proof; not natural semantic inference.', ['CAMPAIGN3_REASON_QUALIFICATION.md']), (2373, 'CORRELATION', 'Same source duplicate fully discounted; disjoint event bases stack; partial overlap exact1/5.', 'Disjoint IDs are declared evidence independence, not proof of statistical independence. Aggregate union fixes collective fixture, not arbitrary subset/correlation law.', ['CAMPAIGN3_MULTISOURCE_PUBLIC_QUALIFICATION.md', 'CAMPAIGN3_REASON_QUALIFICATION.md']), (2401, 'STANDING', 'Acquired standing modifies existing motive; absent Caregiving base stays absent and weak real base rescued.', 'Commitment-as-Need corrected to concrete referent, with separate standing referent fix. Cannot infer all nonzero history crosses integer modifier.', ['CAMPAIGN3_COMMIT_QUALIFICATION.md', 'CAMPAIGN3_REASON_QUALIFICATION.md']), (2466, 'SITUATION-GRAMMAR', 'Retrieved memory changes modifier not base; four independent motives produce four convolved dice.', 'Fixed support grammar not global need for dice nor extra die per descriptive fact.', ['CAMPAIGN3_REASON_QUALIFICATION.md', 'CAMPAIGN3_DECISION_QUALIFICATION.md']), (2491, 'CALIBRATION', 'Compiled d8+1 probability change exceeds d8-to-d10 step in named comparison.', 'Changing earning unit changes threshold to earn+1, never the already compiled+1 value. Later summary repeated old phrasing needs this correction.', ['CAMPAIGN3_HISTORY_LIMITATIONS_CHECKPOINT.md']), (2519, 'OLD-NEW', 'One balanced old/new pair shares probability/mode/action, labels differ.', 'Single equality does not prove every old phenotype under new compiler. Legacy tests pinned explicitly in later rebaseline.', ['CAMPAIGN3_HISTORY_HQ004_CHECKPOINT.md']), (2534, 'SEED-REVISIONS', 'Missing motive,40/60 quantization ties, temporary100-round correction and excluded permanent commitment all preserved.', '500-round Auto lock not proof every magnitude/horizon; restoring recurring-dilemma scope justified, lifecycle needs independent proof. WorkPersistence and CommitmentFidelity not interchangeable causes.', ['CAMPAIGN3_COMMIT_QUALIFICATION.md', 'CAMPAIGN3_IDENTITY_ABLATION_SUMMARY_REV2.json']), (2597, 'AUDIT-CLAIMS', 'Four checks and three commitment passes preserve exact revisions; presence-list lifecycle exercised without lifecycle owner.', 'Later COMMIT supplies native transitions; original tests do not establish every terminal transition or independent external approval of all later work.', ['CAMPAIGN3_COMMIT_QUALIFICATION.md', 'CAMPAIGN3_HISTORY_COUNTEREXAMPLES_CHECKPOINT.md']), (2679, 'ATTRIBUTION-DIRECTION', 'Normalized participant shares preserve single-participant weights; opposite directions distinct across compiles.', 'Causal nonparticipant still unsupported; positive/negative base in one compile nets one reason. Exact source boundary reviewed in HQ007.', ['CAMPAIGN3_HISTORY_HQ007_CHECKPOINT.md', 'CAMPAIGN3_REASON_QUALIFICATION.md']), (2749, 'QUESTIONS-CLASSIFICATION', 'DERIVED labels mean bounded exact-key and source-overlap sufficiency with preserved controls.', 'Not lossless history reduction, universal independence, global dice necessity or all old behaviors rerun under new compiler. Calibration correction still applies.', ['CAMPAIGN3_HISTORY_HQ004_CHECKPOINT.md', 'CAMPAIGN3_HISTORY_LIMITATIONS_CHECKPOINT.md']), (2801, 'TRANSFER-GATES', 'Typed separate reasons, roles, provenance and frozen expressions preserve explanation/query obligations.', 'Frozen expression is not automatic execution replay under changed code. Full17-item met prose still carries nonparticipant/direction/calibration scope; no Campaign3 exit.', ['CAMPAIGN3_HISTORY_HQ007_CHECKPOINT.md', 'CAMPAIGN3_DECISION_QUALIFICATION.md']), (2922, 'FINAL-REBASELINE', 'Default reasonNuclei plus explicit legacy helpers preserves old experiments;32 then3 failures and canary retained.', '328 historical tests/UI smoke not fresh/current UI qualification. Phase2.9/2.95 tests remain legacy, not wholesale new-compiler revalidation.', ['CAMPAIGN3_HISTORY_HQ005_DISPOSITION.md', 'CAMPAIGN3_HISTORY_HQ004_CHECKPOINT.md'])]

rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source']!=SOURCE or not 1494<=u['location']['startLine']<=2982:continue
  assert u['location']['endLine']<=2982
  _,name,claim,limits,paths=max((s for s in specs if s[0]<=u['location']['startLine']),key=lambda s:s[0])
  rows.append(dict(occurrenceId=u['id'],location=u['location'],text=u['text'],claim=name,disposition=claim,limits=limits,evidence=paths))
raw=(B/'sources'/SOURCE).read_bytes();assert Path(SOURCE).read_bytes().startswith(raw)
lines=raw.decode('utf-8-sig').splitlines(keepends=True)
for r in rows:assert ''.join(lines[r['location']['startLine']-1:r['location']['endLine']])==r['text']
assert {n for r in rows for n in range(r['location']['startLine'],r['location']['endLine']+1)}=={n for n in range(1494,2983) if lines[n-1].strip()}
evidence=[]
for n in sorted({n for s in specs for n in s[4]}):
 p=P/n;evidence.append(dict(path=p.as_posix(),sha256=sha(p)))
v=dict(status='HQ011 REBASELINE IDENTITY AND REASONS HISTORY REVIEWED; WIDER AUDIT OPEN',source=dict(path=SOURCE,frozenSha256=sha(B/'sources'/SOURCE)),rows=rows,evidence=evidence,obligations=['RO-C3-001','RO-C3-004','RO-C3-005','RO-C3-006','RO-C3-007','RO-C3-008','RO-C3-009','RO-C3-010','RO-C3-011','RO-C3-012','RO-C3-013','RO-C3-014','RO-C3-015','RO-C3-016','RO-C3-017','RO-C3-019','RO-C3-020','RO-C3-021'],limits=['No fresh production simulation, test suite or build. Receipt bindings do not assert current source freshness for every old receipt.','Thirty reviewed claim groups retain independent public/component, law and historical correction scopes.'],nextGate='Whole reference research log reviewed in scope; remaining source-role, extraction-boundary and historical authority reconciliation.')
save(O/'review.json',v)
c=dict(status=v['status'],originalOccurrences=len(rows),claimGroups=len(specs),indexedWholeOccurrenceLinks=1082+len(rows),freshBehavioralTests=0,reviewSha256=sha(O/'review.json'),checkerSha256=sha(__file__))
save(O/'check.json',c);print(json.dumps(c))
